window.RP_SESSION={"id":"S-e8abd9dd4ed6","messages":[{"id":"RP-II-0173106","time":"2026-08-29T21:50:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"대장간의 화로에 불이 지펴집니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173107","time":"2026-08-29T21:50:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"브랜은… 엥?","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173108","time":"2026-08-29T21:50:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아니 허그네요!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173109","time":"2026-08-29T21:50:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 묵직한 보따리 하나를 들고 옵니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173110","time":"2026-08-29T21:51:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그 안에는 원뿔 모양의 철제 가시 쇠붙이들과 손잡이가 달린 기다란 철 막대기, 끝이 드라이버 처럼 납작하게 눌려 무언가를 떼어내기에 좋을 듯 한 조각 도구 등이 들어있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173111","time":"2026-08-29T21:52:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"+허그의 신발 밑 사이즈에 맞는 황색의 무른 철판과 못들도요!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173112","time":"2026-08-29T21:52:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그의 철퇴는 굉장히 과격한 무기입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173113","time":"2026-08-29T21:53:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"원심력을 실어서 휘두르기에 중간에 공격을 무를 수도 없고, 어디에 잘못 맞았다간 어젯밤 처럼 가시가 떨어져 나가는 둥 상해버리기가 쉽지요.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173114","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"쇠 사슬이 끊어져 부서지거나 철구가 못쓸정도로 망가져버리는게 아니면, 이런 가시가 몇개 떨어져 나가는 정도는 허그가 대강 고치곤 핼었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173115","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"어설픈 용 ⃢맹","profile":"어설픈 용 ⃢맹","identity":"unresolved","type":"dialogue","body":"*개구린데요?","characters":[]},{"id":"RP-II-0173116","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"물론 대강이라 금방 떨어져나가죠!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173117","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"깨꿀.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173118","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무튼 여이! 스러우니까 한잔 해요","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173119","time":"2026-08-29T21:54:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무튼!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173120","time":"2026-08-29T21:55:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"열이 오른 화로, 허그는 처음 써보는 대장간에 이러다간 길드원에게 혼날지도 모르겠다 싶었지만…\n화로만 잠깐 쓰고 갈테니 다들 이정도는 너그러이 생각해 주겠지 싶습니다~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173121","time":"2026-08-29T21:56:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“캬~ 오랜만에 써보는구만 이녀석들도!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173122","time":"2026-08-29T21:56:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"우선 허그는 손잡이가 달린 기다란 쇠막대를 화로에 슬쩍…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173123","time":"2026-08-29T21:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"음! 뜨끈~하게 잘 데워진 듯 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173124","time":"2026-08-29T21:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"조각 도구도 데우고…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173125","time":"2026-08-29T21:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“읏차, 한 번 해보자고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173126","time":"2026-08-29T21:58:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"절그럭, 허그는 철퇴를 허리춤에서 꺼내 낮은 의자에 앉은 뒤, 다리 사이에 철구를 끼워둡니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173127","time":"2026-08-29T21:59:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러곤 깽- 깽- 깽-","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173128","time":"2026-08-29T21:59:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"사슬 손잡이를 망치 삼아서 조각 도구의 끝을 두드리며, 철구에 남아있는 철제 가시의 밑동을 날립니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173129","time":"2026-08-29T21:59:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“흡…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173130","time":"2026-08-29T22:00:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄하, 그래. 이렇게 하는 거였지, 이제 좀 기억이 나는걸~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173131","time":"2026-08-29T22:01:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고선 쇠막대를 다시 데우고…\n한 손으로는 쇠막대를!\n가죽장갑을 낀 다른 손으로는 보따리를 뒤적거려 원뿔형 쇠붙이를 하나 집어들고","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173133","time":"2026-08-29T22:01:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"치이이이익…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173134","time":"2026-08-29T22:02:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"철구에 좁고 낮은 홈을 만듭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173135","time":"2026-08-29T22:03:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"쇠붙이도 비슷한 식으로 살짝 녹인 뒤, 홈에 맞춰 끼우고, 꾹~ 쇠막대의 손잡이로 누르면~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173136","time":"2026-08-29T22:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"짠! 날아간 두 가시 중 하나가 돌아왔습니다.\n…좀 어설프긴 하지만 허그는 이정도면 만족스러운 듯 싶습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173137","time":"2026-08-29T22:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"나머지 가시 하나도 이런 식으로 밑동을 날리고, 붙이고, 눌러서 잘 어찌저찌 해둔 뒤\n슬쩍… 허그는 신발을 벗습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173138","time":"2026-08-29T22:05:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이번에도 우선 조각 도구로 깡깡깡! 이번엔 신발 밑에 달린 스파이크 쇠판을 신발에 박힌 못 째로 뒤집어 떼어냅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173139","time":"2026-08-29T22:06:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"다시 쇠막대를 데우고, 보따리에서 꺼낸 멀끔한 판떼기를 꾸욱~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173140","time":"2026-08-29T22:07:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"막대와 닿은 누런 쇠판의 부분이 녹으며 조금씩 아래로 패여들어갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173141","time":"2026-08-29T22:09:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"다시, 그 자리에 원뿔 쇠붙이를 뒤집어 끼우고 깡깡깡- 이렇게 여러번 반복해서 스파이크가 달린 밑판 둘을 만듭니다.\n못으로 신발의 아래에 잘 박고~ 길드 마룻바닥이 상하지 않도록 두꺼운 가죽 밑창에 신발을 올려서 끈으로 잘 묶으면","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173142","time":"2026-08-29T22:09:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이! 일단은 끝인 것 같은걸.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173143","time":"2026-08-29T22:10:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"가시가 날아간 철퇴도 제법 멀쩡히 돌아오고, 닳아서 상한 신발의 스파이크도 잘 고쳐냈습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173144","time":"2026-08-29T22:11:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“크으~ 옛날생각 나는걸. 그땐 정말 전부 다 처음이었어서 말이지, 철퇴는 엄한 가시를 날려버리질 않나, 신발은 바닥 째로 뜯어버리질 않나.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173145","time":"2026-08-29T22:12:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“확실히, 뭐든지 오래 하면은 언젠가는 잘 되는 것 같다니깐?\n여이, 누가 오기 전에 잘 주워담고~“\n\n절그럭 절그럭…\n\n”이것도 끄고…“\n\n화로를 끄고…\n\n”음, 잘 쓰다 간다고~ 여이!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173146","time":"2026-08-29T22:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"투타타타… 길드로 돌아갑시다!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173147","time":"2026-08-29T22:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"아무튼 그렇게 허그 다-큐멘터리—그래서 상한 장비는 어떻게 하나요? 편은 막을 내립니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173148","time":"2026-08-29T22:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"끗!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173149","time":"2026-08-29T22:13:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0173150","time":"2026-08-29T22:13:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
